async function ladeAufgaben() {
  try {
    const antwort = await fetch('/api/tasks/');
    if (!antwort.ok) {
      throw new Error(`Status ${antwort.status}`);
    }
    return await antwort.json();
  } catch (fehler) {
    console.error(fehler);
  }
}

